from typing import List

class Solution:
    def minimumRefill(self, plants: List[int], capacityA: int, capacityB: int) -> int:
        a, b = capacityA, capacityB
        refills = 0
        l, r = 0, len(plants) - 1
        while l < r:
            if a < plants[l]:
                a = capacityA
                refills += 1
            a -= plants[l]
            l += 1
            if b < plants[r]:
                b = capacityB
                refills += 1
            b -= plants[r]
            r -= 1
        if l == r:
            can = a if a >= b else b
            if can < plants[l]:
                refills += 1
        return refills

