from typing import List

class Solution:
    def minimumRefill(self, plants: List[int], capacityA: int, capacityB: int) -> int:
        n = len(plants)

        def sweep(start, end, cap):
            refills, cur = 0, cap
            step = 1 if start <= end else -1
            for i in range(start, end, step):
                if cur < plants[i]:
                    cur = cap
                    refills += 1
                cur -= plants[i]
            return refills, cur

        m = n // 2
        ra, la = sweep(0, m, capacityA)
        rb, lb = sweep(n - 1, m if n % 2 else m - 1, capacityB)
        extra = 0
        if n % 2 and max(la, lb) < plants[m]:
            extra = 1
        return ra + rb + extra

