class Solution {
    private long[] sweep(int[] p, int start, int end, int cap) {
        int refills = 0;
        long cur = cap;
        int step = start <= end ? 1 : -1;
        for (int i = start; i != end; i += step) {
            if (cur < p[i]) { cur = cap; refills++; }
            cur -= p[i];
        }
        return new long[]{refills, cur};
    }

    public int minimumRefill(int[] plants, int capacityA, int capacityB) {
        int n = plants.length, m = n / 2;
        long[] a = sweep(plants, 0, m, capacityA);
        long[] b = sweep(plants, n - 1, n % 2 == 1 ? m : m - 1, capacityB);
        int extra = (n % 2 == 1 && Math.max(a[1], b[1]) < plants[m]) ? 1 : 0;
        return (int) (a[0] + b[0] + extra);
    }
}

