    const n = plants.length, m = Math.floor(n / 2);
    const sweep = (start, end, cap) => {
        let refills = 0, cur = cap;
        const step = start <= end ? 1 : -1;
        for (let i = start; i !== end; i += step) {
            if (cur < plants[i]) { cur = cap; refills++; }
            cur -= plants[i];
        }
        return [refills, cur];
    };
    const [ra, la] = sweep(0, m, capacityA);
    const [rb, lb] = sweep(n - 1, n % 2 ? m : m - 1, capacityB);
    const extra = n % 2 && Math.max(la, lb) < plants[m] ? 1 : 0;
    return ra + rb + extra;
};
